using InkRecognition;
using System.Text.Json;
using var input=JsonDocument.Parse(File.ReadAllBytes(args[0]));var t=LegacyCursiveSeparationTable.Load(File.ReadAllBytes(args[1]));var rows=new List<object>();
foreach(var row in input.RootElement.GetProperty("Rows").EnumerateArray()){var strokes=row.GetProperty("CutInk").EnumerateArray().Select(s=>new InkStroke(s.EnumerateArray().Select(p=>new InkPoint(p[0].GetSingle(),p[1].GetSingle())).ToArray())).ToArray();var ink=LegacyCursivePreparedInk.Create(strokes);var groups=new List<int[]>();foreach(var g in row.GetProperty("Groups").EnumerateArray()){var ranges=g.GetProperty("Stored").EnumerateArray().Select(v=>new LegacyInkRange(v[0].GetInt32(),v[1].GetInt32(),v[2].GetInt32())).ToArray();int value=LegacyCursiveGroupSeparationCost.Evaluate(ink,ranges,row.GetProperty("Height").GetSingle(),.2f,3f,t.Values.Span,0x4000000);groups.Add(new[]{g.GetProperty("Group").GetInt32(),value});}rows.Add(new{Name=row.GetProperty("Name").GetString(),Groups=groups});}File.WriteAllText(args[2],JsonSerializer.Serialize(rows));
